// Shared helpers for the auto-signed standard NDA tests (#0224f4 #1d9069) — spec: .qa/e2e/specs/hunter-nda.md §3–4.
import { expect, Page, Locator } from '@playwright/test';

export const composer = (p: Page): Locator => p.getByPlaceholder('כתיבת הודעה');
export const sendBtn = (p: Page): Locator => p.getByRole('button', { name: 'שליחה', exact: true });
export const waitingBar = (p: Page, other: string) => p.getByText(`ממתינים לאישור של ${other} ל-NDA`);
export const requestBar = (p: Page, initiator: string) => p.getByText(`${initiator} פנו אליכם`);

/** Today in Israel as dd.mm.yyyy. */
export function todayIL(): string {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jerusalem', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date());
  return parts.replace(/\//g, '.');
}

/** dd.mm.yyyy + 3 calendar months, same day. */
export function plus3Months(ddmmyyyy: string): string {
  const [d, m, y] = ddmmyyyy.split('.').map(Number);
  const dt = new Date(Date.UTC(y, m - 1 + 3, d));
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${pad(dt.getUTCDate())}.${pad(dt.getUTCMonth() + 1)}.${dt.getUTCFullYear()}`;
}

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');

/** Opens «צפייה ב-NDA» and returns the normalised innerText of the «NDA סטנדרטי» dialog; closes it with Escape. */
export async function readNdaView(p: Page): Promise<string> {
  await p.getByText('צפייה ב-NDA').first().click();
  const dlg = p.getByRole('dialog').filter({ hasText: 'NDA סטנדרטי' });
  await expect(dlg).toBeVisible({ timeout: 30_000 });
  await expect(dlg.getByText('פרטי ההסכם')).toBeVisible();
  const text = (await dlg.innerText()).replace(/[‎‏]/g, '');
  await p.keyboard.press('Escape');
  await expect(dlg).toBeHidden();
  return text;
}

/** Asserts «פרטי ההסכם» label/value pairs (RTL-safe regex on innerText). */
export function expectDetails(text: string, pairs: Record<string, string | RegExp>) {
  for (const [label, value] of Object.entries(pairs)) {
    const v = value instanceof RegExp ? value.source : esc(value);
    expect(text, `«פרטי ההסכם» — ${label} ${value}`).toMatch(new RegExp(`${esc(label)}\\s*${v}`));
  }
}

export async function expectComposerBlocked(p: Page, who: string) {
  await expect(composer(p), `${who}: «כתיבת הודעה» disabled`).toBeDisabled();
  await expect(sendBtn(p), `${who}: «שליחה» disabled`).toBeDisabled();
}
